import React, { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import { userAPI, petsAPI, adminAPI } from "../services/api";
import "./UserDashboard.css";

const UserDashboard = () => {
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState("dashboard");
  const [lostReports, setLostReports] = useState([]);
  const [rescueReports, setRescueReports] = useState([]);
  const [allLostReports, setAllLostReports] = useState([]);
  const [availableAdoptionPets, setAvailableAdoptionPets] = useState([]);
  const [myAdoptionPosts, setMyAdoptionPosts] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [submitLoading, setSubmitLoading] = useState(false);
  const [successMessage, setSuccessMessage] = useState("");

  const [profileData, setProfileData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone_no: "",
    address: "",
    city: "",
    state: "",
    pincode: "",
    gender: "",
    profile_picture: null,
  });
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileImage, setProfileImage] = useState(null);
  const [profileImagePreview, setProfileImagePreview] = useState(null);
  // Only for navbar profile image
  const profileImageUrl = user?.profile_picture || null;

  // Pet report form state
  const [petForm, setPetForm] = useState({
    pet_name: "",
    pet_type: "Dog",
    pet_breed: "",
    pet_age: "",
    pet_colour: "",
    pet_weight: "",
    pet_gender: "Male",
    pet_location: "",
    pet_state: "",
    pet_city: "",
    pet_status: "lost",
    description: "",
    is_vaccinated: false,
    is_diseased: false,
    vaccination_details: "",
    health_conditions: "",
    pet_image: null,
  });

  // --- Dashboard Additions ---
  // Load user reports function
  const loadUserReports = async () => {
    try {
      const res = await userAPI.getUserReports();
      setLostReports(res.data.reports || []);
    } catch (err) {
      setError("Failed to load user reports.");
    }
  };
  // Forgot Password Section
  const [forgotEmail, setForgotEmail] = useState("");
  const [forgotPassword, setForgotPassword] = useState("");
  const [forgotConfirm, setForgotConfirm] = useState("");
  const [forgotMsg, setForgotMsg] = useState("");

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    setForgotMsg("");
    try {
      const res = await userAPI.forgotPassword(
        forgotEmail,
        forgotPassword,
        forgotConfirm
      );
      setForgotMsg(res.data.message || "Password updated successfully.");
    } catch (err) {
      setForgotMsg(err.response?.data?.error || "Error resetting password.");
    }
  };

  // User Stories Section
  const [stories, setStories] = useState([]);
  const [storyContent, setStoryContent] = useState("");
  const [storyPetId, setStoryPetId] = useState("");
  const [storyMsg, setStoryMsg] = useState("");

  // Post Pet for Adoption Form
  const [postAdoptionForm, setPostAdoptionForm] = useState({
    name: "",
    type: "",
    breed: "",
    age: "",
    gender: "",
    description: "",
    location: "",
    image: null,
    is_vaccinated: false,
    is_diseased: false,
    disease_description: "",
    vaccination_date: "",
    vaccination_type: "",
    vaccination_certificate: null,
  });

  const loadStories = async () => {
    try {
      const res = await userAPI.getUserStories();
      setStories(res.data.stories || []);
    } catch {}
  };
  useEffect(() => {
    loadStories();
  }, []);

  const handlePostStory = async (e) => {
    e.preventDefault();
    setStoryMsg("");
    try {
      await userAPI.postUserStory(storyContent, storyPetId);
      setStoryMsg("Story posted!");
      setStoryContent("");
      setStoryPetId("");
      loadStories();
    } catch (err) {
      setStoryMsg("Error posting story.");
    }
  };

  // Favourite Pets Section
  const [favourites, setFavourites] = useState([]);
  const [favMsg, setFavMsg] = useState("");
  const loadFavourites = async () => {
    try {
      const res = await userAPI.getFavouritePets();
      setFavourites(res.data.favourites || []);
    } catch {}
  };
  useEffect(() => {
    loadFavourites();
  }, []);

  const handleAddFavourite = async (petId) => {
    setFavMsg("");
    try {
      await userAPI.addFavouritePet(petId);
      setFavMsg("Added to favourites.");
      loadFavourites();
    } catch (err) {
      setFavMsg("Error adding favourite.");
    }
  };

  const handleRemoveFavourite = async (favouriteId) => {
    setFavMsg("");
    try {
      await userAPI.removeFavouritePet(favouriteId);
      setFavMsg("Removed from favourites.");
      loadFavourites();
    } catch (err) {
      setFavMsg("Error removing favourite.");
    }
  };

  // --- Admin Dashboard Metrics Section ---
  const [adminMetrics, setAdminMetrics] = useState(null);
  const [metricsMsg, setMetricsMsg] = useState("");

  const loadAdminMetrics = async () => {
    setMetricsMsg("");
    try {
      const res = await adminAPI.getDashboardMetrics();
      setAdminMetrics(res.data.metrics || null);
    } catch (err) {
      setMetricsMsg("Error loading metrics.");
    }
  };
  // Call this in useEffect if user is admin
  // useEffect(() => { if (user?.role === 'admin') loadAdminMetrics(); }, [user]);
  // --- Example JSX ---
  /*
  {user?.role === 'admin' && adminMetrics && (
    <div className="admin-metrics">
      <h3>Admin Dashboard Metrics</h3>
      <ul>
        <li>Total Pets Reported: {adminMetrics.total_pets_reported}</li>
        <li>Total Adoptions Approved: {adminMetrics.total_adoptions_approved}</li>
        <li>Total Lost: {adminMetrics.total_lost}</li>
        <li>Total Found: {adminMetrics.total_found}</li>
        <li>Total Registered Users: {adminMetrics.total_registered_users}</li>
        <li>Total Cases Resolved: {adminMetrics.total_cases_resolved}</li>
      </ul>
      {metricsMsg && <div>{metricsMsg}</div>}
    </div>
  )}
  */

  // --- Placeholder for remaining REST APIs ---
  // TODO: Build Get All Registered Users API (Admin)
  // TODO: Build Pet Adoption Request API (if not already built)
  // TODO: Build Update Report Status API (Admin)
  // TODO: Build any other missing APIs from your requirements

  useEffect(() => {
    loadData();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const loadData = async () => {
    setLoading(true);
    setError("");
    try {
      // Load notifications
      await loadNotifications();

      // Load all lost reports for public viewing
      await loadAllLostReports();

      // Load available adoption pets
      await loadAvailableAdoptionPets();

      // Load my adoption posts
      await loadMyAdoptionPosts();

      // Load profile data
      await loadProfile();

      // Load real user reports from backend
      const reportsResponse = await userAPI.getUserReports();

      if (reportsResponse.data.success) {
        const { lost, found } = reportsResponse.data.reports;
        const mappedLostReports = lost.map((report) => ({
          ...report,
          photo: report.photo || getDefaultImage(report.animal_type),
        }));
        const mappedRescueReports = found.map((report) => ({
          ...report,
          photo: report.photo || getDefaultImage(report.animal_type),
        }));
        setLostReports(mappedLostReports);
        setRescueReports(mappedRescueReports);
      } else {
        setLostReports([]);
        setRescueReports([]);
      }
    } catch (err) {
      setError("Failed to load data. Please try again.");
      console.error("Error loading data:", err);

      // Set empty arrays on error
      setLostReports([]);
    }
    setLoading(false);
  };

  // Helper function to get default images based on pet type
  const getDefaultImage = (animalType) => {
    const defaultImages = {
      CAT: "https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=300&h=200&fit=crop",
      DOG: "https://images.unsplash.com/photo-1552053831-71594a27632d?w=300&h=200&fit=crop",
      BIRD: "https://images.unsplash.com/photo-1444464666168-49d633b86797?w=300&h=200&fit=crop",
      OTHER:
        "https://images.unsplash.com/photo-1425082661705-1834bfd09dca?w=300&h=200&fit=crop",
    };
    return defaultImages[animalType] || defaultImages["OTHER"];
  };

  const loadNotifications = async () => {
    try {
      const response = await userAPI.getUserNotifications();
      if (response.data.success) {
        const notificationData = response.data.notifications || [];
        setNotifications(notificationData);
        // Count unread notifications
        const unread = notificationData.filter(
          (notification) => !notification.is_read
        ).length;
        setUnreadCount(unread);
      }
    } catch (err) {
      console.error("Error loading notifications:", err);
    }
  };

  const loadAllLostReports = async () => {
    try {
      console.log("Loading all lost reports...");
      const response = await userAPI.getAllLostReports();
      console.log("All lost reports response:", response.data);

      if (response.data.success) {
        const reports = response.data.reports || [];
        console.log("Found", reports.length, "lost reports");
        setAllLostReports(reports);
      } else {
        console.error("API returned success=false:", response.data);
        setAllLostReports([]);
      }
    } catch (err) {
      console.error("Error loading all lost reports:", err);
      console.error("Error details:", err.response?.data);
      setAllLostReports([]);
    }
  };

  const loadAvailableAdoptionPets = async () => {
    try {
      console.log("Loading available adoption pets...");
      const response = await userAPI.getAvailableAdoptionPets();
      console.log("Available adoption pets response:", response.data);

      if (response.data.success) {
        const pets = response.data.pets || [];
        console.log("Found", pets.length, "available adoption pets");
        setAvailableAdoptionPets(pets);
      } else {
        console.error("API returned success=false:", response.data);
        setAvailableAdoptionPets([]);
      }
    } catch (err) {
      console.error("Error loading adoption pets:", err);
      console.error("Error details:", err.response?.data);
      setAvailableAdoptionPets([]);
    }
  };

  const loadMyAdoptionPosts = async () => {
    try {
      console.log("Loading my adoption posts...");
      const response = await petsAPI.getMyAdoptionPosts();
      console.log("My adoption posts response:", response.data);

      if (response.data.success) {
        const posts = response.data.adoption_posts || [];
        console.log("Found", posts.length, "adoption posts");
        setMyAdoptionPosts(posts);
      } else {
        console.error("API returned success=false:", response.data);
        setMyAdoptionPosts([]);
      }
    } catch (err) {
      console.error("Error loading my adoption posts:", err);
      console.error("Error details:", err.response?.data);
      setMyAdoptionPosts([]);
    }
  };

  const loadProfile = async () => {
    try {
      const response = await userAPI.getUserDetails();
      if (response.data.success) {
        const userData = response.data.user;
        setProfileData({
          first_name: userData.first_name || "",
          last_name: userData.last_name || "",
          email: userData.email || "",
          phone_no: userData.phone_no || "",
          address: userData.address || "",
          city: userData.city || "",
          state: userData.state || "",
          pincode: userData.pincode || "",
          gender: userData.gender || "",
          profile_picture: userData.profile_picture,
        });

        if (userData.profile_picture) {
          setProfileImagePreview(userData.profile_picture);
        }
      }
    } catch (err) {
      console.error("Error loading profile:", err);
    }
  };

  const handleProfileImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setProfileImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      const formData = new FormData();
      Object.keys(profileData).forEach((key) => {
        if (key !== "profile_picture" && profileData[key]) {
          formData.append(key, profileData[key]);
        }
      });

      if (profileImage) {
        formData.append("profile_picture", profileImage);
      }

      const response = await userAPI.updateProfile(formData);
      if (response.data.success) {
        setSuccessMessage("Profile updated successfully!");
        setIsEditingProfile(false);
        await loadProfile(); // Reload profile data
      } else {
        setError(response.data.error || "Failed to update profile");
      }
    } catch (err) {
      setError(
        "Error updating profile: " + (err.response?.data?.error || err.message)
      );
    } finally {
      setSubmitLoading(false);
    }
  };

  const handleProfileInputChange = (e) => {
    const { name, value } = e.target;
    setProfileData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleNotificationDropdownToggle = async () => {
    const newShowState = !showNotifications;
    setShowNotifications(newShowState);

    // If opening notifications and there are unread ones, mark all as read
    if (newShowState && unreadCount > 0) {
      try {
        await userAPI.markAllNotificationsRead();
        // Update local state
        const updatedNotifications = notifications.map((notification) => ({
          ...notification,
          is_read: true,
        }));
        setNotifications(updatedNotifications);
        setUnreadCount(0);
      } catch (err) {
        console.error("Error marking notifications as read:", err);
      }
    }
  };

  const handleDeleteNotification = async (notificationId) => {
    try {
      await userAPI.deleteNotification(notificationId);
      // Remove from local state
      const updatedNotifications = notifications.filter(
        (n) => n.id !== notificationId
      );
      setNotifications(updatedNotifications);
      // Recalculate unread count
      const unread = updatedNotifications.filter(
        (notification) => !notification.is_read
      ).length;
      setUnreadCount(unread);
    } catch (err) {
      console.error("Error deleting notification:", err);
    }
  };

  const handleDeleteReport = async (reportId) => {
    if (!window.confirm("Are you sure you want to delete this report?")) {
      return;
    }

    try {
      await userAPI.deleteReport(reportId);
      // Reload reports data
      await loadUserReports();
      setSuccessMessage("Report deleted successfully!");
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err) {
      console.error("Error deleting report:", err);
      setError("Failed to delete report. Please try again.");
      setTimeout(() => setError(""), 3000);
    }
  };

  const handleMarkReport = async (reportId, status) => {
    try {
      await userAPI.updateReportStatus(reportId, status);
      // Reload reports data
      await loadUserReports();
      setSuccessMessage(`Report marked as ${status.toLowerCase()}!`);
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err) {
      console.error("Error updating report status:", err);
      setError("Failed to update report status. Please try again.");
      setTimeout(() => setError(""), 3000);
    }
  };

  const handleFormChange = (e) => {
    const { name, value, type, checked } = e.target;
    setPetForm((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleSubmitPetReport = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      // Create FormData for file upload
      const formData = new FormData();

      // Add all form fields
      Object.keys(petForm).forEach((key) => {
        if (key === "pet_image" && petForm[key]) {
          formData.append("pet_image", petForm[key]);
        } else if (key !== "pet_image") {
          formData.append(key, petForm[key]);
        }
      });

      const response = await petsAPI.submitPetRequestWithImage(formData);
      if (response.data.success) {
        setSuccessMessage(
          `${
            petForm.pet_status.charAt(0).toUpperCase() +
            petForm.pet_status.slice(1)
          } pet report submitted successfully!`
        );
        // Reset form
        setPetForm({
          pet_name: "",
          pet_type: "Dog",
          pet_breed: "",
          pet_age: "",
          pet_colour: "",
          pet_weight: "",
          pet_gender: "Male",
          pet_location: "",
          pet_state: "",
          pet_city: "",
          pet_status: "lost",
          description: "",
          is_vaccinated: false,
          is_diseased: false,
          vaccination_details: "",
          health_conditions: "",
          pet_image: null,
        });
        // Reload data to show updated reports
        await loadData();
        // Switch back to dashboard tab
        setTimeout(() => {
          setActiveTab("dashboard");
        }, 2000);
      }
    } catch (err) {
      setError(
        err.response?.data?.error ||
          "Failed to submit pet report. Please try again."
      );
    }
    setSubmitLoading(false);
  };

  const renderReportCard = (report) => (
    <div key={report.id} className="dashboard-pet-card">
      <div className="pet-card-image">
        <img
          src={report.photo}
          alt={report.pet_name}
          onError={(e) => {
            e.target.src = getDefaultImage(report.animal_type);
          }}
        />
        <div className="pet-name-overlay">
          <h3>{report.pet_name}</h3>
        </div>
      </div>
      <div className="pet-card-info">
        <div className="pet-type">{report.animal_type}</div>
        <div className="pet-details">
          {report.pet_breed && (
            <span className="pet-breed">{report.pet_breed}</span>
          )}
          {report.pet_location && (
            <span className="pet-location">📍 {report.pet_location}</span>
          )}
        </div>
        <div className="pet-description">
          {report.description
            ? report.description.length > 50
              ? `${report.description.substring(0, 50)}...`
              : report.description
            : "No description available"}
        </div>
        <div className="report-meta">
          <span className="report-date">
            {new Date(report.created_at).toLocaleDateString()}
          </span>
        </div>
        <div className={`pet-status-badge ${report.status.toLowerCase()}`}>
          {report.status}
        </div>
        <div className="report-actions">
          {report.status !== "FOUND" && report.status !== "REUNITED" && (
            <div className="mark-buttons">
              {report.report_type === "LOST" && report.status !== "FOUND" && (
                <button
                  className="btn-mark-found"
                  onClick={() => handleMarkReport(report.id, "FOUND")}
                  title="Mark as Found"
                >
                  <span className="material-icons">check_circle</span>
                  Found
                </button>
              )}
              {report.status !== "REUNITED" && (
                <button
                  className="btn-mark-reunited"
                  onClick={() => handleMarkReport(report.id, "REUNITED")}
                  title="Mark as Reunited"
                >
                  <span className="material-icons">favorite</span>
                  Reunited
                </button>
              )}
            </div>
          )}
          <button
            className="btn-delete-report"
            onClick={() => handleDeleteReport(report.id)}
            title="Delete Report"
          >
            <span className="material-icons">delete</span>
          </button>
        </div>
      </div>
    </div>
  );

  const renderPublicReportCard = (report) => (
    <div key={report.id} className="dashboard-pet-card public-report">
      <div className="pet-card-image">
        <img
          src={report.photo}
          alt={report.pet_name}
          onError={(e) => {
            e.target.src = getDefaultImage(report.animal_type);
          }}
        />
        <div className="pet-name-overlay">
          <h3>{report.pet_name}</h3>
        </div>
      </div>
      <div className="pet-card-info">
        <div className="pet-type">{report.animal_type}</div>
        <div className="pet-details">
          {report.pet_breed && (
            <span className="pet-breed">{report.pet_breed}</span>
          )}
          {report.pet_location && (
            <span className="pet-location">📍 {report.pet_location}</span>
          )}
        </div>
        <div className="pet-description">
          {report.description
            ? report.description.length > 80
              ? `${report.description.substring(0, 80)}...`
              : report.description
            : "No description available"}
        </div>
        <div className="report-meta">
          <span className="report-date">
            {new Date(report.created_at).toLocaleDateString()}
          </span>
          <span className="report-owner">
            By: {report.owner_username || "Anonymous"}
          </span>
        </div>
        <div className={`pet-status-badge ${report.status.toLowerCase()}`}>
          {report.status}
        </div>
        <div className="contact-info">
          {report.contact_info && (
            <div className="contact-details">
              <span className="material-icons">contact_phone</span>
              <span className="contact-text">Contact owner for details</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <div className="header-content">
          <div className="logo">
            <span>PET_RESCUE_APP</span>
          </div>
          <div className="header-center">
            <span>WELCOME: {user?.username?.toUpperCase() || "USER_NAME"}</span>
          </div>
          <div className="header-right">
            <div className="navbar-icons">
              <button
                className="refresh-btn"
                onClick={loadData}
                disabled={loading}
                title="Refresh Data"
              >
                <span className="material-icons">refresh</span>
              </button>
              <div
                className="notification-bell"
                onClick={handleNotificationDropdownToggle}
              >
                <span className="material-icons">notifications</span>
                {unreadCount > 0 && (
                  <span className="notification-count">{unreadCount}</span>
                )}
                {showNotifications && (
                  <div className="notification-dropdown">
                    <div className="notification-header">
                      <h3>Notifications</h3>
                      <button
                        className="notification-close"
                        onClick={(e) => {
                          e.stopPropagation();
                          setShowNotifications(false);
                        }}
                      >
                        ×
                      </button>
                    </div>
                    <div className="notification-list">
                      {notifications.length === 0 ? (
                        <div className="no-notifications">
                          <span className="material-icons">
                            notifications_none
                          </span>
                          <p>No notifications yet</p>
                        </div>
                      ) : (
                        notifications.map((notification) => (
                          <div
                            key={notification.id}
                            className={`notification-item ${
                              notification.is_read ? "read" : "unread"
                            }`}
                          >
                            <div className="notification-content">
                              <h4>{notification.title}</h4>
                              <p>{notification.message}</p>
                              <span className="notification-time">
                                {new Date(
                                  notification.created_at
                                ).toLocaleDateString()}
                              </span>
                            </div>
                            <button
                              className="delete-notification"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleDeleteNotification(notification.id);
                              }}
                            >
                              <span className="material-icons">delete</span>
                            </button>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
              <div className="navbar-profile-widget">
                <span
                  className="material-icons navbar-profile-icon"
                  tabIndex={0}
                  onClick={() => setShowProfileDropdown((prev) => !prev)}
                >
                  person
                </span>
                {showProfileDropdown && (
                  <div className="profile-dropdown">
                    <button
                      className="profile-dropdown-item"
                      onClick={() => {
                        setActiveTab("profile");
                        setShowProfileDropdown(false);
                      }}
                    >
                      Edit
                    </button>
                    <button
                      className="profile-dropdown-item"
                      onClick={() => {
                        // Clear token from localStorage
                        localStorage.removeItem("token");

                        // Optionally clear other user-related data
                        // localStorage.removeItem('user');

                        // Redirect to login page
                        window.location.href = "/login";
                      }}
                    >
                      Logout
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
        {/* Horizontal Navigation Bar */}
        <nav className="horizontal-nav">
          <ul className="nav-menu">
            <li
              className={activeTab === "dashboard" ? "active" : ""}
              onClick={() => setActiveTab("dashboard")}
            >
              <span className="material-icons">dashboard</span>
              DASHBOARD
            </li>
            <li
              className={activeTab === "report-lost" ? "active" : ""}
              onClick={() => setActiveTab("report-lost")}
            >
              <span className="material-icons">report</span>
              REPORT LOST PET
            </li>
            <li
              className={activeTab === "report-found" ? "active" : ""}
              onClick={() => setActiveTab("report-found")}
            >
              <span className="material-icons">visibility</span>
              REPORT FOUND PET
            </li>
            <li
              className={activeTab === "all-lost" ? "active" : ""}
              onClick={() => setActiveTab("all-lost")}
            >
              <span className="material-icons">pets</span>
              ALL LOST PET
            </li>
            <li
              className={activeTab === "explore-adoption" ? "active" : ""}
              onClick={() => setActiveTab("explore-adoption")}
            >
              <span className="material-icons">favorite</span>
              EXPLORE ADOPTION
            </li>
            <li
              className={activeTab === "notifications" ? "active" : ""}
              onClick={() => setActiveTab("notifications")}
            >
              <span className="material-icons">notifications</span>
              NOTIFICATIONS
            </li>
          </ul>
        </nav>
      </header>

      <div className="dashboard-content">
        <main className="main-content">
          {error && <div className="error-message">{error}</div>}
          {successMessage && (
            <div className="success-message">{successMessage}</div>
          )}

          {activeTab === "dashboard" &&
            (loading ? (
              <div className="loading">Loading...</div>
            ) : (
              <div className="dashboard-sections">
                <div className="reports-section">
                  <div className="section-header">
                    <span className="material-icons">list</span>
                    YOUR LOST REPORTS ({lostReports.length})
                  </div>
                  <div className="reports-grid">
                    {lostReports.length > 0 ? (
                      lostReports.map((report) => (
                        <div key={report.id} className="dashboard-pet-card">
                          <div className="pet-card-image">
                            <img
                              src={report.photo}
                              alt={report.pet_name}
                              onError={(e) => {
                                e.target.src = getDefaultImage(
                                  report.animal_type
                                );
                              }}
                            />
                            <div className="pet-name-overlay">
                              <h3>{report.pet_name}</h3>
                            </div>
                          </div>
                          <div className="pet-card-info">
                            <div className="pet-type">{report.animal_type}</div>
                            <div className="pet-details">
                              {report.pet_breed && (
                                <span className="pet-breed">
                                  {report.pet_breed}
                                </span>
                              )}
                              {report.pet_location && (
                                <span className="pet-location">
                                  📍 {report.pet_location}
                                </span>
                              )}
                            </div>
                            <div className="pet-description">
                              {report.description
                                ? report.description.length > 50
                                  ? `${report.description.substring(0, 50)}...`
                                  : report.description
                                : "No description available"}
                            </div>
                            <div className="report-meta">
                              <span className="report-date">
                                {new Date(
                                  report.created_at
                                ).toLocaleDateString()}
                              </span>
                            </div>
                            <div
                              className={`pet-status-badge ${report.status.toLowerCase()}`}
                            >
                              Status:{" "}
                              <strong>{report.status.toUpperCase()}</strong>
                            </div>
                            {/* Show 'Reunite' button only if status is 'APPROVED' and not already reunited */}
                            {report.status &&
                              report.status.toUpperCase() === "APPROVED" &&
                              !report.is_reunited && (
                                <button
                                  className="btn-mark-reunited"
                                  onClick={() =>
                                    handleMarkReport(report.id, "REUNITED")
                                  }
                                >
                                  Reunite Pet
                                </button>
                              )}
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="no-reports">
                        <span className="material-icons">pets</span>
                        <p>No lost pet reports yet</p>
                        <button
                          className="btn-create-report"
                          onClick={() => setActiveTab("report-lost")}
                        >
                          Report Lost Pet
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                <div className="reports-section">
                  <div className="section-header">
                    <span className="material-icons">list</span>
                    YOUR RESCUE PET REPORTS ({rescueReports.length})
                  </div>
                  <div className="reports-grid">
                    {rescueReports.length > 0 ? (
                      rescueReports.map((report) => (
                        <div key={report.id} className="dashboard-pet-card">
                          <div className="pet-card-image">
                            <img
                              src={report.photo}
                              alt={report.pet_name}
                              onError={(e) => {
                                e.target.src = getDefaultImage(
                                  report.animal_type
                                );
                              }}
                            />
                            <div className="pet-name-overlay">
                              <h3>{report.pet_name}</h3>
                            </div>
                          </div>
                          <div className="pet-card-info">
                            <div className="pet-type">{report.animal_type}</div>
                            <div className="pet-details">
                              {report.pet_breed && (
                                <span className="pet-breed">
                                  {report.pet_breed}
                                </span>
                              )}
                              {report.pet_location && (
                                <span className="pet-location">
                                  📍 {report.pet_location}
                                </span>
                              )}
                            </div>
                            <div className="pet-description">
                              {report.description
                                ? report.description.length > 50
                                  ? `${report.description.substring(0, 50)}...`
                                  : report.description
                                : "No description available"}
                            </div>
                            <div className="report-meta">
                              <span className="report-date">
                                {new Date(
                                  report.created_at
                                ).toLocaleDateString()}
                              </span>
                            </div>
                            <div
                              className={`pet-status-badge ${report.status.toLowerCase()}`}
                            >
                              Status:{" "}
                              <strong>{report.status.toUpperCase()}</strong>
                            </div>
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="no-reports">
                        <span className="material-icons">visibility</span>
                        <p>No rescue pet reports yet</p>
                        <button
                          className="btn-create-report"
                          onClick={() => setActiveTab("report-found")}
                        >
                          Report Rescue Pet
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                {user?.role === "admin" && adminMetrics && (
                  <div className="admin-metrics">
                    <h3>Admin Dashboard Metrics</h3>
                    <ul>
                      <li>
                        Total Pets Reported: {adminMetrics.total_pets_reported}
                      </li>
                      <li>
                        Total Adoptions Approved:{" "}
                        {adminMetrics.total_adoptions_approved}
                      </li>
                      <li>Total Lost: {adminMetrics.total_lost}</li>
                      <li>Total Found: {adminMetrics.total_found}</li>
                      <li>
                        Total Registered Users:{" "}
                        {adminMetrics.total_registered_users}
                      </li>
                      <li>
                        Total Cases Resolved:{" "}
                        {adminMetrics.total_cases_resolved}
                      </li>
                    </ul>
                    {metricsMsg && <div>{metricsMsg}</div>}
                  </div>
                )}
              </div>
            ))}

          {activeTab === "report-lost" && (
            <div className="form-section">
              <div className="section-header">
                <span className="material-icons">report</span>
                REPORT LOST PET
              </div>
              <form
                onSubmit={handleSubmitPetReport}
                className="pet-report-form"
              >
                <input type="hidden" name="pet_status" value="lost" />

                <div className="form-grid">
                  <div className="form-group">
                    <label>Pet Name *</label>
                    <input
                      type="text"
                      name="pet_name"
                      value={petForm.pet_name}
                      onChange={handleFormChange}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Pet Type *</label>
                    <select
                      name="pet_type"
                      value={petForm.pet_type}
                      onChange={handleFormChange}
                      required
                    >
                      <option value="Dog">Dog</option>
                      <option value="Cat">Cat</option>
                      <option value="Bird">Bird</option>
                      <option value="Other">Other</option>
                    </select>
                  </div>

                  <div className="form-group">
                    <label>Breed</label>
                    <input
                      type="text"
                      name="pet_breed"
                      value={petForm.pet_breed}
                      onChange={handleFormChange}
                    />
                  </div>

                  <div className="form-group">
                    <label>Age</label>
                    <input
                      type="number"
                      name="pet_age"
                      value={petForm.pet_age}
                      onChange={handleFormChange}
                      min="0"
                    />
                  </div>

                  <div className="form-group">
                    <label>Color</label>
                    <input
                      type="text"
                      name="pet_colour"
                      value={petForm.pet_colour}
                      onChange={handleFormChange}
                    />
                  </div>

                  <div className="form-group">
                    <label>Weight (kg)</label>
                    <input
                      type="number"
                      name="pet_weight"
                      value={petForm.pet_weight}
                      onChange={handleFormChange}
                      step="0.1"
                      min="0"
                    />
                  </div>

                  <div className="form-group">
                    <label>Gender</label>
                    <select
                      name="pet_gender"
                      value={petForm.pet_gender}
                      onChange={handleFormChange}
                    >
                      <option value="Male">Male</option>
                      <option value="Female">Female</option>
                      <option value="Unknown">Unknown</option>
                    </select>
                  </div>

                  <div className="form-group">
                    <label>Last Seen Location *</label>
                    <input
                      type="text"
                      name="pet_location"
                      value={petForm.pet_location}
                      onChange={handleFormChange}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>State</label>
                    <input
                      type="text"
                      name="pet_state"
                      value={petForm.pet_state}
                      onChange={handleFormChange}
                    />
                  </div>

                  <div className="form-group">
                    <label>City</label>
                    <input
                      type="text"
                      name="pet_city"
                      value={petForm.pet_city}
                      onChange={handleFormChange}
                    />
                  </div>

                  <div className="form-group full-width">
                    <label>Pet Photo</label>
                    <input
                      type="file"
                      name="pet_image"
                      accept="image/*"
                      onChange={(e) => {
                        const file = e.target.files[0];
                        setPetForm((prev) => ({
                          ...prev,
                          pet_image: file,
                        }));
                      }}
                      className="file-input"
                    />
                    <div className="file-input-helper">
                      Choose a clear photo of your pet (JPG, PNG, WebP)
                    </div>
                    {petForm.pet_image && (
                      <div className="image-preview">
                        <img
                          src={URL.createObjectURL(petForm.pet_image)}
                          alt="Pet preview"
                          className="preview-image"
                        />
                        <button
                          type="button"
                          className="remove-image"
                          onClick={() =>
                            setPetForm((prev) => ({ ...prev, pet_image: null }))
                          }
                        >
                          Remove
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                <div className="form-group full-width">
                  <label>Description</label>
                  <textarea
                    name="description"
                    value={petForm.description}
                    onChange={handleFormChange}
                    rows="4"
                    placeholder="Describe your pet's appearance, behavior, any distinctive marks..."
                  />
                </div>

                <div className="form-section-title">Medical Information</div>
                <div className="form-grid">
                  <div className="form-group checkbox-group">
                    <label>
                      <input
                        type="checkbox"
                        name="is_vaccinated"
                        checked={petForm.is_vaccinated}
                        onChange={handleFormChange}
                      />
                      Is Vaccinated
                    </label>
                  </div>

                  {petForm.is_vaccinated && (
                    <div className="form-group full-width">
                      <label>Vaccination Details</label>
                      <input
                        type="text"
                        name="vaccination_details"
                        value={petForm.vaccination_details}
                        onChange={handleFormChange}
                        placeholder="Enter vaccination details (e.g., Rabies, Distemper, etc.)..."
                      />
                    </div>
                  )}

                  <div className="form-group checkbox-group">
                    <label>
                      <input
                        type="checkbox"
                        name="is_diseased"
                        checked={petForm.is_diseased}
                        onChange={handleFormChange}
                      />
                      Is Diseased
                    </label>
                  </div>

                  {petForm.is_diseased && (
                    <div className="form-group full-width">
                      <label>Health Conditions</label>
                      <input
                        type="text"
                        name="health_conditions"
                        value={petForm.health_conditions}
                        onChange={handleFormChange}
                        placeholder="Describe health conditions..."
                      />
                    </div>
                  )}
                </div>

                <div className="form-actions">
                  <button
                    type="button"
                    className="btn-cancel"
                    onClick={() => setActiveTab("dashboard")}
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="btn-submit"
                    disabled={submitLoading}
                  >
                    {submitLoading ? "Submitting..." : "Report Lost Pet"}
                  </button>
                </div>
              </form>
            </div>
          )}

          {activeTab === "report-found" && (
            <div className="form-section">
              <div className="section-header">
                <span className="material-icons">visibility</span>
                REPORT FOUND PET
              </div>
              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  setSubmitLoading(true);
                  setError("");
                  setSuccessMessage("");

                  const foundFormData = { ...petForm, pet_status: "found" };

                  petsAPI
                    .submitPetRequest(foundFormData)
                    .then((response) => {
                      if (response.data.success) {
                        setSuccessMessage(
                          "Found pet report submitted successfully!"
                        );
                        setPetForm({
                          pet_name: "",
                          pet_type: "Dog",
                          pet_breed: "",
                          pet_age: "",
                          pet_colour: "",
                          pet_weight: "",
                          pet_gender: "Male",
                          pet_location: "",
                          pet_state: "",
                          pet_city: "",
                          pet_status: "found",
                          description: "",
                          is_vaccinated: false,
                          is_diseased: false,
                          vaccination_details: "",
                          health_conditions: "",
                        });
                        loadData();
                        setTimeout(() => setActiveTab("dashboard"), 2000);
                      }
                    })
                    .catch((err) => {
                      setError(
                        err.response?.data?.error ||
                          "Failed to submit found pet report. Please try again."
                      );
                    })
                    .finally(() => setSubmitLoading(false));
                }}
                className="pet-report-form"
              >
                {/* Same form fields as lost pet but with different title and submit text */}
                <div className="form-grid">
                  <div className="form-group">
                    <label>Pet Name (if known)</label>
                    <input
                      type="text"
                      name="pet_name"
                      value={petForm.pet_name}
                      onChange={handleFormChange}
                    />
                  </div>

                  <div className="form-group">
                    <label>Pet Type *</label>
                    <select
                      name="pet_type"
                      value={petForm.pet_type}
                      onChange={handleFormChange}
                      required
                    >
                      <option value="Dog">Dog</option>
                      <option value="Cat">Cat</option>
                      <option value="Bird">Bird</option>
                      <option value="Other">Other</option>
                    </select>
                  </div>

                  <div className="form-group">
                    <label>Breed (if known)</label>
                    <input
                      type="text"
                      name="pet_breed"
                      value={petForm.pet_breed}
                      onChange={handleFormChange}
                    />
                  </div>

                  <div className="form-group">
                    <label>Found Location *</label>
                    <input
                      type="text"
                      name="pet_location"
                      value={petForm.pet_location}
                      onChange={handleFormChange}
                      required
                    />
                  </div>

                  <div className="form-group full-width">
                    <label>Pet Photo</label>
                    <input
                      type="file"
                      name="pet_image"
                      accept="image/*"
                      onChange={(e) => {
                        const file = e.target.files[0];
                        setPetForm((prev) => ({
                          ...prev,
                          pet_image: file,
                        }));
                      }}
                      className="file-input"
                    />
                    <div className="file-input-helper">
                      Upload a photo of the found pet
                    </div>
                    {petForm.pet_image && (
                      <div className="image-preview">
                        <img
                          src={URL.createObjectURL(petForm.pet_image)}
                          alt="Pet preview"
                          className="preview-image"
                        />
                        <button
                          type="button"
                          className="remove-image"
                          onClick={() =>
                            setPetForm((prev) => ({ ...prev, pet_image: null }))
                          }
                        >
                          Remove
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                <div className="form-group full-width">
                  <label>Description *</label>
                  <textarea
                    name="description"
                    value={petForm.description}
                    onChange={handleFormChange}
                    rows="4"
                    placeholder="Describe the found pet's appearance, condition, behavior..."
                    required
                  />
                </div>

                <div className="form-actions">
                  <button
                    type="button"
                    className="btn-cancel"
                    onClick={() => setActiveTab("dashboard")}
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="btn-submit"
                    disabled={submitLoading}
                  >
                    {submitLoading ? "Submitting..." : "Report Found Pet"}
                  </button>
                </div>
              </form>
            </div>
          )}

          {activeTab === "notifications" && (
            <div className="notifications-section">
              <div className="section-header">
                <span className="material-icons">notifications</span>
                NOTIFICATIONS
              </div>
              <div className="notifications-list">
                {notifications.length === 0 ? (
                  <div className="no-notifications">No notifications yet</div>
                ) : (
                  notifications.map((notification) => (
                    <div
                      key={notification.id}
                      className={`notification-item ${
                        notification.is_read ? "read" : "unread"
                      }`}
                    >
                      <div className="notification-message">
                        {notification.message}
                      </div>
                      <div className="notification-time">
                        {new Date(notification.created_at).toLocaleDateString()}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}

          {activeTab === "all-lost" && (
            <div className="all-lost-reports">
              <div className="section-header">
                <span className="material-icons">search</span>
                ALL APPROVED LOST PETS (
                {
                  allLostReports.filter(
                    (r) =>
                      r.report_type === "LOST" && r.report_status === "ACCEPTED"
                  ).length
                }
                )
              </div>
              <div className="reports-grid">
                {loading ? (
                  <div className="loading">
                    Loading approved lost pet reports...
                  </div>
                ) : allLostReports.filter(
                    (r) =>
                      r.report_type === "LOST" && r.report_status === "ACCEPTED"
                  ).length > 0 ? (
                  allLostReports
                    .filter(
                      (r) =>
                        r.report_type === "LOST" &&
                        r.report_status === "ACCEPTED"
                    )
                    .map((report) => (
                      <div
                        key={report.id}
                        className="dashboard-pet-card public-report"
                      >
                        <div className="pet-card-image">
                          <img
                            src={report.photo || "/default-pet.png"}
                            alt={report.pet_name}
                            onError={(e) => {
                              e.target.src = "/default-pet.png";
                            }}
                          />
                          <div className="pet-name-overlay">
                            <h3>{report.pet_name}</h3>
                          </div>
                        </div>
                        <div className="pet-card-info">
                          <div className="pet-type">{report.animal_type}</div>
                          <div className="pet-details">
                            {report.pet_breed && (
                              <span className="pet-breed">
                                {report.pet_breed}
                              </span>
                            )}
                            {report.pet_location && (
                              <span className="pet-location">
                                📍 {report.pet_location}
                              </span>
                            )}
                          </div>
                          <div className="pet-description">
                            {report.description
                              ? report.description.length > 80
                                ? `${report.description.substring(0, 80)}...`
                                : report.description
                              : "No description available"}
                          </div>
                          <div className="report-meta">
                            <span className="report-date">
                              {new Date(report.created_at).toLocaleDateString()}
                            </span>
                            <span className="report-owner">
                              By: {report.owner_username || "Anonymous"}
                            </span>
                          </div>
                          <div className={`pet-status-badge approved`}>
                            APPROVED - LOST
                          </div>
                          <div className="contact-info">
                            <div className="contact-details">
                              <span className="material-icons">
                                contact_phone
                              </span>
                              <span className="contact-text">
                                Contact owner to help reunite
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    ))
                ) : (
                  <div className="no-reports">
                    <span className="material-icons">search_off</span>
                    <p>
                      No approved lost pet reports from community members yet
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === "explore-adoption" && (
            <div className="explore-adoption-section">
              <div className="section-header">
                <span className="material-icons">favorite</span>
                EXPLORE PETS AVAILABLE FOR ADOPTION ({availableAdoptionPets.length})
              </div>
              <div className="reports-grid">
                {loading ? (
                  <div className="loading">Loading available pets...</div>
                ) : availableAdoptionPets.length > 0 ? (
                  availableAdoptionPets.map((pet) => (
                    <div key={pet.id} className="dashboard-pet-card adoption-card">
                      <div className="pet-card-image">
                        <img
                          src={pet.image || "/default-pet.png"}
                          alt={pet.name}
                          onError={(e) => {
                            e.target.src = "/default-pet.png";
                          }}
                        />
                        <div className="pet-name-overlay">
                          <h3>{pet.name}</h3>
                        </div>
                      </div>
                      <div className="pet-card-info">
                        <div className="pet-type">{pet.type}</div>
                        <div className="pet-details">
                          {pet.breed && (
                            <span className="pet-breed">{pet.breed}</span>
                          )}
                          <span className="pet-age">🎂 {pet.age} years old</span>
                          <span className="pet-gender">
                            {pet.gender === "Male" ? "♂️" : "♀️"} {pet.gender}
                          </span>
                          {pet.location && (
                            <span className="pet-location">📍 {pet.location}</span>
                          )}
                        </div>
                        <div className="pet-description">
                          {pet.description
                            ? pet.description.length > 100
                              ? `${pet.description.substring(0, 100)}...`
                              : pet.description
                            : "No description available"}
                        </div>
                        <div className="pet-medical-info">
                          {pet.is_vaccinated && (
                            <span className="badge vaccinated">✓ Vaccinated</span>
                          )}
                          {pet.is_diseased && (
                            <span className="badge health-issue">⚠ Health Condition</span>
                          )}
                        </div>
                        <div className="pet-status-badge available-adoption">
                          AVAILABLE FOR ADOPTION
                        </div>
                        <div className="adoption-actions">
                          {pet.has_pending_request ? (
                            <button className="btn-pending" disabled>
                              <span className="material-icons">schedule</span>
                              Request Pending
                            </button>
                          ) : (
                            <button
                              className="btn-adopt"
                              onClick={async () => {
                                try {
                                  setSubmitLoading(true);
                                  setError("");
                                  // Call adoption request API
                                  await petsAPI.requestAdoption({
                                    pet_id: pet.id,
                                    reason: "I would like to adopt this pet",
                                  });
                                  setSuccessMessage(
                                    "Adoption request submitted! Admin will review your request."
                                  );
                                  // Reload data to update button state
                                  await loadData();
                                  setTimeout(() => setSuccessMessage(""), 3000);
                                } catch (err) {
                                  setError(
                                    err.response?.data?.error ||
                                      "Failed to submit adoption request. Please try again."
                                  );
                                } finally {
                                  setSubmitLoading(false);
                                }
                              }}
                              disabled={submitLoading}
                            >
                              <span className="material-icons">pets</span>
                              Request Adoption
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="no-reports">
                    <span className="material-icons">pets</span>
                    <p>No pets available for adoption at the moment</p>
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === "profile" && (
            <div className="profile-section-content">
              <div className="section-header">
                <span className="material-icons">person</span>
                PROFILE MANAGEMENT
              </div>

              <div className="profile-container">
                <div className="profile-image-section">
                  <div className="profile-image-large">
                    {profileImagePreview ? (
                      <img
                        src={profileImagePreview}
                        alt="Profile"
                        className="profile-image-display"
                      />
                    ) : (
                      <div className="profile-image-placeholder-large">
                        <span className="material-icons">person</span>
                      </div>
                    )}
                  </div>

                  {isEditingProfile && (
                    <div className="image-upload-section">
                      <label
                        htmlFor="profile-image-input"
                        className="upload-btn"
                      >
                        <span className="material-icons">photo_camera</span>
                        Change Photo
                      </label>
                      <input
                        id="profile-image-input"
                        type="file"
                        accept="image/*"
                        onChange={handleProfileImageChange}
                        style={{ display: "none" }}
                      />
                    </div>
                  )}
                </div>

                <div className="profile-details">
                  <div className="profile-header">
                    <h3>
                      {profileData.first_name}{" "}
                      {profileData.last_name || user?.username}
                    </h3>
                    <p className="user-email">{profileData.email}</p>

                    {!isEditingProfile ? (
                      <button
                        className="btn-edit-profile"
                        onClick={() => setIsEditingProfile(true)}
                      >
                        <span className="material-icons">edit</span>
                        Edit Profile
                      </button>
                    ) : (
                      <div className="edit-profile-actions">
                        <button
                          className="btn-save-profile"
                          onClick={handleProfileSubmit}
                          disabled={submitLoading}
                        >
                          <span className="material-icons">save</span>
                          {submitLoading ? "Saving..." : "Save Changes"}
                        </button>
                        <button
                          className="btn-cancel-profile"
                          onClick={() => {
                            setIsEditingProfile(false);
                            setProfileImage(null);
                            setProfileImagePreview(profileData.profile_picture);
                          }}
                        >
                          <span className="material-icons">cancel</span>
                          Cancel
                        </button>
                      </div>
                    )}
                  </div>

                  {isEditingProfile ? (
                    <form
                      onSubmit={handleProfileSubmit}
                      className="profile-edit-form"
                    >
                      <div className="form-row">
                        <div className="form-group">
                          <label>First Name</label>
                          <input
                            type="text"
                            name="first_name"
                            value={profileData.first_name}
                            onChange={handleProfileInputChange}
                            placeholder="Enter first name"
                          />
                        </div>
                        <div className="form-group">
                          <label>Last Name</label>
                          <input
                            type="text"
                            name="last_name"
                            value={profileData.last_name}
                            onChange={handleProfileInputChange}
                            placeholder="Enter last name"
                          />
                        </div>
                      </div>

                      <div className="form-row">
                        <div className="form-group">
                          <label>Email</label>
                          <input
                            type="email"
                            name="email"
                            value={profileData.email}
                            onChange={handleProfileInputChange}
                            placeholder="Enter email address"
                          />
                        </div>
                        <div className="form-group">
                          <label>Phone Number</label>
                          <input
                            type="tel"
                            name="phone_no"
                            value={profileData.phone_no}
                            onChange={handleProfileInputChange}
                            placeholder="Enter phone number"
                          />
                        </div>
                      </div>

                      <div className="form-row">
                        <div className="form-group">
                          <label>City</label>
                          <input
                            type="text"
                            name="city"
                            value={profileData.city}
                            onChange={handleProfileInputChange}
                            placeholder="Enter city"
                          />
                        </div>
                        <div className="form-group">
                          <label>State</label>
                          <input
                            type="text"
                            name="state"
                            value={profileData.state}
                            onChange={handleProfileInputChange}
                            placeholder="Enter state"
                          />
                        </div>
                      </div>

                      <div className="form-row">
                        <div className="form-group">
                          <label>PIN Code</label>
                          <input
                            type="text"
                            name="pincode"
                            value={profileData.pincode}
                            onChange={handleProfileInputChange}
                            placeholder="Enter PIN code"
                          />
                        </div>
                        <div className="form-group">
                          <label>Gender</label>
                          <select
                            name="gender"
                            value={profileData.gender}
                            onChange={handleProfileInputChange}
                          >
                            <option value="">Select Gender</option>
                            <option value="Male">Male</option>
                            <option value="Female">Female</option>
                            <option value="Other">Other</option>
                          </select>
                        </div>
                      </div>

                      <div className="form-group full-width">
                        <label>Address</label>
                        <textarea
                          name="address"
                          value={profileData.address}
                          onChange={handleProfileInputChange}
                          placeholder="Enter complete address"
                          rows="3"
                        />
                      </div>
                    </form>
                  ) : (
                    <div className="profile-view">
                      <div className="profile-info-grid">
                        <div className="info-item">
                          <span className="info-label">Phone:</span>
                          <span className="info-value">
                            {profileData.phone_no || "Not provided"}
                          </span>
                        </div>
                        <div className="info-item">
                          <span className="info-label">City:</span>
                          <span className="info-value">
                            {profileData.city || "Not provided"}
                          </span>
                        </div>
                        <div className="info-item">
                          <span className="info-label">State:</span>
                          <span className="info-value">
                            {profileData.state || "Not provided"}
                          </span>
                        </div>
                        <div className="info-item">
                          <span className="info-label">PIN Code:</span>
                          <span className="info-value">
                            {profileData.pincode || "Not provided"}
                          </span>
                        </div>
                        <div className="info-item">
                          <span className="info-label">Gender:</span>
                          <span className="info-value">
                            {profileData.gender || "Not provided"}
                          </span>
                        </div>
                        <div className="info-item full-width">
                          <span className="info-label">Address:</span>
                          <span className="info-value">
                            {profileData.address || "Not provided"}
                          </span>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default UserDashboard;
